// Copies Cymbra Music's showcase media from the capture harness's output into the site
// (change: add-site-music-showcase, D1): `yarn sync:music-media`.
//
// Sources: `apps/music/store/<CAPTURE_SOURCE>/<lang>/` (the gallery) and
// `apps/music/store/video/<lang>/` (the video and its poster), both generated by the
// harness; `yarn sync:music-media it` copies one language's alone. The copies are
// byte-for-byte; `test/music-media.spec.ts` fails when one drifts from its source.
// Re-run after `melos run screenshots` or `showcase-video`.

import { copyFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { LANGS, isLang, type Lang } from "../src/lib/i18n.ts";
import {
  CAPTURE_SOURCE,
  GALLERY,
  MEDIA_DIR,
  POSTER_FILE,
  VIDEO_FILE,
  VIDEO_SOURCE,
} from "../src/lib/music-media.ts";

const site = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const store = resolve(site, "../music/store");

// The languages to make, every one by default: `yarn sync:music-media it` makes Italian's
// files alone, so that adding a language moves none of the others' (change:
// add-site-italian-locale, D4).
const asked = process.argv.slice(2);
for (const arg of asked) {
  if (!isLang(arg)) throw new Error(`not a site language: ${arg} (one of ${LANGS.join(", ")})`);
}
const langs: readonly Lang[] = asked.length ? (asked as Lang[]) : LANGS;

for (const lang of langs) {
  const into = resolve(site, MEDIA_DIR, lang);
  mkdirSync(into, { recursive: true });
  const pairs = [
    ...GALLERY.map((s) => [resolve(store, CAPTURE_SOURCE, lang, s.file), s.file]),
    ...[VIDEO_FILE, POSTER_FILE].map((f) => [resolve(store, VIDEO_SOURCE, lang, f), f]),
  ];
  for (const [from, name] of pairs) {
    copyFileSync(from, resolve(into, name));
  }
  console.log(`${lang}: ${pairs.length} files → ${MEDIA_DIR}/${lang}/`);
}
